<script setup lang="ts">import{onMounted,ref}from'vue';import{wmApi}from'../api';import{ApiError,type Material}from'@leadnews/shared';import{ElMessage}from'element-plus';const rows=ref<Material[]>([]),busy=ref(false);async function load(){rows.value=await wmApi.materials()}async function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;busy.value=true;try{await wmApi.upload(f);ElMessage.success('上传成功');await load()}catch(x){ElMessage.error(x instanceof ApiError?x.message:'上传失败')}finally{busy.value=false}}async function remove(id:number){try{await wmApi.deleteMaterial(id);await load()}catch(x){ElMessage.error(x instanceof ApiError?x.message:'删除失败')}}onMounted(load)</script><template><section class="panel"><div class="toolbar"><h1 style="flex:1">图片素材</h1><label><input hidden type="file" accept="image/png,image/jpeg,image/webp" @change="upload"><el-button :loading="busy">上传图片</el-button></label></div><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px"><article v-for="m in rows" :key="m.id"><img :src="m.url" class="cover" style="width:100%"><p class="meta">素材 #{{m.id}}</p><el-button text type="danger" @click="remove(m.id)">删除</el-button></article></div><div v-if="!rows.length" class="empty">暂无素材</div></section></template>
